INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','third-mixed-conditionals','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"third-mixed-conditionals","title":"Third and mixed conditionals","level":"B2","order":43,"summary":"Look back at an unreal past and connect past conditions with present consequences.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An unreal past condition","Possible and certain imagined results","Past condition, present result","Present condition, past result"],"rules":[{"title":"An unreal past condition","explanation":"The usual **third conditional** imagines a past that did not happen. Use if + past perfect for the condition and would have + past participle for the result. The grammar shows both parts as alternatives to the actual past.","pattern":"If I **had called**, she **would have waited**.","commonMistakes":["Had and would have do different jobs. Do not routinely put would have in the if clause of this standard pattern."],"examples":["Use the third conditional: “If she **had prepared** the visitor guide yesterday, we would have finished on time.”","Use the third conditional: “If she **had restored** the old portrait yesterday, we would have finished on time.”"],"skill":"form"},{"title":"Possible and certain imagined results","explanation":"Could have or might have can replace would have when the imagined result is ability or possibility rather than the expected consequence. Keep the same perfect construction after the modal.","pattern":"We **might have won** if we had trained more.","commonMistakes":["Could have is not always interchangeable with would have; the strength or kind of result changes."],"examples":["Complete the third-conditional result: “If we had had more time yesterday, we **would have prepared** the visitor guide.”","Complete the third-conditional result: “If we had had more time yesterday, we **would have restored** the old portrait.”"],"skill":"meaning"},{"title":"Past condition, present result","explanation":"A mixed conditional can link an unreal past condition to a present result. The if-clause stays past perfect, but the present result normally uses would + base verb. Explicit time words help the reader follow the link.","pattern":"If I **had studied** medicine, I **would be** a doctor now.","commonMistakes":["Do not force have into a present result merely because the condition is past."],"examples":["Complete the present result of a mixed conditional: “If she had prepared the visitor guide yesterday, she **would be** free now.”","Complete the present result of a mixed conditional: “If she had restored the old portrait yesterday, she **would be** free now.”"],"skill":"contrast"},{"title":"Present condition, past result","explanation":"A continuing hypothetical state can explain an unreal past result. Use if + past simple for the imagined state and would have + participle for the past result. Match each clause to its own time instead of memorising one fixed pair.","pattern":"If I **were** more organised, I **would have remembered** yesterday.","commonMistakes":["The label mixed describes the time relationship, not an error in tense consistency."],"examples":["Complete the past result of a mixed conditional: “If I were more organised, I **would have prepared** the visitor guide yesterday.”","Complete the past result of a mixed conditional: “If I were more organised, I **would have restored** the old portrait yesterday.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"1b2254b3-f237-5be4-a5cd-cf90716aeeb7","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Use the third conditional: “If she ____ the visitor guide yesterday, we would have finished on time.”","choices":[{"id":"A","text":"has prepared"},{"id":"B","text":"had prepared"},{"id":"C","text":"would have prepared"},{"id":"D","text":"had preparing"}],"answerId":"B","hint":"The condition concerns a **different past**, so use past perfect.","explanation":"The unreal past condition is **if + had + prepared**.","keywords":["unreal-past-condition"],"skill":"unreal-past-condition","contextKey":"third-mixed-conditionals-1","fingerprint":"764caa61cc54ee181a4c6c452feabdb82e91f1fadb082e7e7625f8f4b8e344bd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The condition concerns a **different past**, so use past perfect.","The unreal past condition is **if + had + prepared**.","Choose **had prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Present perfect does not mark the unreal past condition requested.","B":"The unreal past condition is **if + had + prepared**.","C":"In the standard third conditional, would have belongs in the result clause.","D":"The past perfect requires a participle, not an -ing form."}}},{"id":"7648efe4-23fb-51c6-a8a2-8de6a92ad5fa","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the third-conditional result: “If we had had more time yesterday, we ____ the visitor guide.”","choices":[{"id":"A","text":"would had prepared"},{"id":"B","text":"would have preparing"},{"id":"C","text":"would have prepared"},{"id":"D","text":"would prepared"}],"answerId":"C","hint":"The result is also in an **unreal past**: use modal + have + participle.","explanation":"The imagined past result uses **would have prepared**.","keywords":["unreal-past-result"],"skill":"unreal-past-result","contextKey":"third-mixed-conditionals-1","fingerprint":"9414e97e312c8e39be7190754189b92bd862f9aa27e0a2a2520a4323826fb03a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The result is also in an **unreal past**: use modal + have + participle.","The imagined past result uses **would have prepared**.","Choose **would have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would takes base have, not had.","B":"Have needs the past participle in this result.","C":"The imagined past result uses **would have prepared**.","D":"The perfect auxiliary have is missing."}}},{"id":"031d909a-bd32-5463-a055-1415234352ba","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the present result of a mixed conditional: “If she had prepared the visitor guide yesterday, she ____ free now.”","choices":[{"id":"A","text":"would been"},{"id":"B","text":"would is"},{"id":"C","text":"would be"},{"id":"D","text":"would have been"}],"answerId":"C","hint":"Read **now**: the condition is past, but the result is present.","explanation":"The result is **now**, so use **would be**, while the past condition keeps had + participle.","keywords":["past-condition-present-result"],"skill":"past-condition-present-result","contextKey":"third-mixed-conditionals-1","fingerprint":"f756e6fa58d14604e6f7997d47024ae1df605ea1243b578b56708029e633af10","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Read **now**: the condition is past, but the result is present.","The result is **now**, so use **would be**, while the past condition keeps had + participle.","Choose **would be**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would requires base be unless have precedes been.","B":"Is cannot follow would.","C":"The result is **now**, so use **would be**, while the past condition keeps had + participle.","D":"This would locate the imagined result in the past, contrary to the specified present result."}}},{"id":"88701465-b088-5736-a486-978d6db51c1d","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the past result of a mixed conditional: “If I were more organised, I ____ the visitor guide yesterday.”","choices":[{"id":"A","text":"would have preparing"},{"id":"B","text":"would have prepared"},{"id":"C","text":"would preparing"},{"id":"D","text":"would had prepared"}],"answerId":"B","hint":"Match the result to **yesterday**, not to the surface tense of the if-clause.","explanation":"The imagined result is yesterday, so it needs **would have prepared** despite the continuing-state condition.","keywords":["present-condition-past-result"],"skill":"present-condition-past-result","contextKey":"third-mixed-conditionals-1","fingerprint":"c5712b2b9ec06569d64782e394d0d00323437ff4188f581fdeed544fc7f24df3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the result to **yesterday**, not to the surface tense of the if-clause.","The imagined result is yesterday, so it needs **would have prepared** despite the continuing-state condition.","Choose **would have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past result in the simple perfect needs a past participle.","B":"The imagined result is yesterday, so it needs **would have prepared** despite the continuing-state condition.","C":"The result needs a perfect construction, not an unsupported -ing form.","D":"After would, use have rather than had."}}},{"id":"ed89cead-7beb-5447-a5c9-8589734a0632","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Use the third conditional: “If she ____ the old portrait yesterday, we would have finished on time.”","choices":[{"id":"A","text":"would have restored"},{"id":"B","text":"had restoring"},{"id":"C","text":"has restored"},{"id":"D","text":"had restored"}],"answerId":"D","hint":"The condition concerns a **different past**, so use past perfect.","explanation":"The unreal past condition is **if + had + restored**.","keywords":["unreal-past-condition"],"skill":"unreal-past-condition","contextKey":"third-mixed-conditionals-2","fingerprint":"910898dff76487390dd311836faeff42cf107536e298a1b6fca9c50d31e6bc3b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The condition concerns a **different past**, so use past perfect.","The unreal past condition is **if + had + restored**.","Choose **had restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In the standard third conditional, would have belongs in the result clause.","B":"The past perfect requires a participle, not an -ing form.","C":"Present perfect does not mark the unreal past condition requested.","D":"The unreal past condition is **if + had + restored**."}}},{"id":"9ce3b5b1-e41f-507a-a219-36308df1829a","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the third-conditional result: “If we had had more time yesterday, we ____ the old portrait.”","choices":[{"id":"A","text":"would have restored"},{"id":"B","text":"would restored"},{"id":"C","text":"would had restored"},{"id":"D","text":"would have restoring"}],"answerId":"A","hint":"The result is also in an **unreal past**: use modal + have + participle.","explanation":"The imagined past result uses **would have restored**.","keywords":["unreal-past-result"],"skill":"unreal-past-result","contextKey":"third-mixed-conditionals-2","fingerprint":"136cf9b034be8a1585f45602779bd41e55c04f57b3c99969db2ede9e11c39aac","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The result is also in an **unreal past**: use modal + have + participle.","The imagined past result uses **would have restored**.","Choose **would have restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The imagined past result uses **would have restored**.","B":"The perfect auxiliary have is missing.","C":"Would takes base have, not had.","D":"Have needs the past participle in this result."}}},{"id":"e71dc7ce-0927-5e77-a32c-b1b66a4bd189","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the present result of a mixed conditional: “If she had restored the old portrait yesterday, she ____ free now.”","choices":[{"id":"A","text":"would have been"},{"id":"B","text":"would been"},{"id":"C","text":"would is"},{"id":"D","text":"would be"}],"answerId":"D","hint":"Read **now**: the condition is past, but the result is present.","explanation":"The result is **now**, so use **would be**, while the past condition keeps had + participle.","keywords":["past-condition-present-result"],"skill":"past-condition-present-result","contextKey":"third-mixed-conditionals-2","fingerprint":"40811030e48cf5187016dce60d7bc9d7c00317e59de7e45c3de7276f308b12ff","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Read **now**: the condition is past, but the result is present.","The result is **now**, so use **would be**, while the past condition keeps had + participle.","Choose **would be**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This would locate the imagined result in the past, contrary to the specified present result.","B":"Would requires base be unless have precedes been.","C":"Is cannot follow would.","D":"The result is **now**, so use **would be**, while the past condition keeps had + participle."}}},{"id":"ef445ad2-9f10-5676-a8bb-aaade4a245cd","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the past result of a mixed conditional: “If I were more organised, I ____ the old portrait yesterday.”","choices":[{"id":"A","text":"would restoring"},{"id":"B","text":"would had restored"},{"id":"C","text":"would have restoring"},{"id":"D","text":"would have restored"}],"answerId":"D","hint":"Match the result to **yesterday**, not to the surface tense of the if-clause.","explanation":"The imagined result is yesterday, so it needs **would have restored** despite the continuing-state condition.","keywords":["present-condition-past-result"],"skill":"present-condition-past-result","contextKey":"third-mixed-conditionals-2","fingerprint":"689fc206d2c330247ae97bb7591760733b9588e1703ade2f25333b0f893736d5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the result to **yesterday**, not to the surface tense of the if-clause.","The imagined result is yesterday, so it needs **would have restored** despite the continuing-state condition.","Choose **would have restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The result needs a perfect construction, not an unsupported -ing form.","B":"After would, use have rather than had.","C":"A past result in the simple perfect needs a past participle.","D":"The imagined result is yesterday, so it needs **would have restored** despite the continuing-state condition."}}},{"id":"217d887d-b4f7-5450-a82a-8c54855c192d","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Use the third conditional: “If she ____ the garden fence yesterday, we would have finished on time.”","choices":[{"id":"A","text":"had measuring"},{"id":"B","text":"has measured"},{"id":"C","text":"had measured"},{"id":"D","text":"would have measured"}],"answerId":"C","hint":"The condition concerns a **different past**, so use past perfect.","explanation":"The unreal past condition is **if + had + measured**.","keywords":["unreal-past-condition"],"skill":"unreal-past-condition","contextKey":"third-mixed-conditionals-3","fingerprint":"4991cfefaf7b0b5bd3c1845f20b4c170892373a4813698d9fb44e1f40914a5f8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The condition concerns a **different past**, so use past perfect.","The unreal past condition is **if + had + measured**.","Choose **had measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The past perfect requires a participle, not an -ing form.","B":"Present perfect does not mark the unreal past condition requested.","C":"The unreal past condition is **if + had + measured**.","D":"In the standard third conditional, would have belongs in the result clause."}}},{"id":"1fe3ccfb-e882-5384-a56d-99e800bbaa79","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the third-conditional result: “If we had had more time yesterday, we ____ the garden fence.”","choices":[{"id":"A","text":"would measured"},{"id":"B","text":"would had measured"},{"id":"C","text":"would have measuring"},{"id":"D","text":"would have measured"}],"answerId":"D","hint":"The result is also in an **unreal past**: use modal + have + participle.","explanation":"The imagined past result uses **would have measured**.","keywords":["unreal-past-result"],"skill":"unreal-past-result","contextKey":"third-mixed-conditionals-3","fingerprint":"c7901026be81b3e4dc4f2acb73d2921c4c280df2264c7ddc90027dc6efa9da8d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The result is also in an **unreal past**: use modal + have + participle.","The imagined past result uses **would have measured**.","Choose **would have measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect auxiliary have is missing.","B":"Would takes base have, not had.","C":"Have needs the past participle in this result.","D":"The imagined past result uses **would have measured**."}}},{"id":"376dc745-af1d-5567-a648-699bddcfd44b","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the present result of a mixed conditional: “If she had measured the garden fence yesterday, she ____ free now.”","choices":[{"id":"A","text":"would be"},{"id":"B","text":"would have been"},{"id":"C","text":"would been"},{"id":"D","text":"would is"}],"answerId":"A","hint":"Read **now**: the condition is past, but the result is present.","explanation":"The result is **now**, so use **would be**, while the past condition keeps had + participle.","keywords":["past-condition-present-result"],"skill":"past-condition-present-result","contextKey":"third-mixed-conditionals-3","fingerprint":"07319301d5b279455fe7b4a01ea55c3484f3c8ba597c0b2ce2b48cb3d39df10e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Read **now**: the condition is past, but the result is present.","The result is **now**, so use **would be**, while the past condition keeps had + participle.","Choose **would be**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The result is **now**, so use **would be**, while the past condition keeps had + participle.","B":"This would locate the imagined result in the past, contrary to the specified present result.","C":"Would requires base be unless have precedes been.","D":"Is cannot follow would."}}},{"id":"a29f12f2-0dea-57ee-a54b-41d4789918b7","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the past result of a mixed conditional: “If I were more organised, I ____ the garden fence yesterday.”","choices":[{"id":"A","text":"would measuring"},{"id":"B","text":"would had measured"},{"id":"C","text":"would have measuring"},{"id":"D","text":"would have measured"}],"answerId":"D","hint":"Match the result to **yesterday**, not to the surface tense of the if-clause.","explanation":"The imagined result is yesterday, so it needs **would have measured** despite the continuing-state condition.","keywords":["present-condition-past-result"],"skill":"present-condition-past-result","contextKey":"third-mixed-conditionals-3","fingerprint":"851ef0324099360c39b10de05b3a881987f54b35de531fd781e7453199b33962","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the result to **yesterday**, not to the surface tense of the if-clause.","The imagined result is yesterday, so it needs **would have measured** despite the continuing-state condition.","Choose **would have measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The result needs a perfect construction, not an unsupported -ing form.","B":"After would, use have rather than had.","C":"A past result in the simple perfect needs a past participle.","D":"The imagined result is yesterday, so it needs **would have measured** despite the continuing-state condition."}}},{"id":"83c10b23-4b56-50ad-a0e3-b811159a5238","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Use the third conditional: “If she ____ the travel leaflet yesterday, we would have finished on time.”","choices":[{"id":"A","text":"would have translated"},{"id":"B","text":"had translating"},{"id":"C","text":"has translated"},{"id":"D","text":"had translated"}],"answerId":"D","hint":"The condition concerns a **different past**, so use past perfect.","explanation":"The unreal past condition is **if + had + translated**.","keywords":["unreal-past-condition"],"skill":"unreal-past-condition","contextKey":"third-mixed-conditionals-4","fingerprint":"2cdb17232eb41caf8ffc05bb738cf772a23da05e0e376c1766a63f855dc67f85","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-third-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The condition concerns a **different past**, so use past perfect.","The unreal past condition is **if + had + translated**.","Choose **had translated**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In the standard third conditional, would have belongs in the result clause.","B":"The past perfect requires a participle, not an -ing form.","C":"Present perfect does not mark the unreal past condition requested.","D":"The unreal past condition is **if + had + translated**."}}},{"id":"a30f265b-0187-5a03-a006-549673768cb6","topicSlug":"third-mixed-conditionals","level":"B2","prompt":"Complete the third-conditional result: “If we had had more time yesterday, we ____ the travel leaflet.”","choices":[{"id":"A","text":"would translated"},{"id":"B","text":"would had tra